package com.grafkom.viewing3d;
import org.lwjgl.stb.STBImage; import org.lwjgl.system.*; import java.nio.*; import static org.lwjgl.opengl.GL11.*; import static org.lwjgl.opengl.GL12.*; import static org.lwjgl.opengl.GL13.*; import static org.lwjgl.opengl.GL30.*;
public final class Texture2D implements AutoCloseable {private final int id;public Texture2D(String path){id=glGenTextures();glBindTexture(GL_TEXTURE_2D,id);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);try(MemoryStack s=MemoryStack.stackPush()){IntBuffer w=s.mallocInt(1),h=s.mallocInt(1),c=s.mallocInt(1);STBImage.stbi_set_flip_vertically_on_load(true);String loadPath=path; java.nio.file.Path extracted=null;
            if(path.startsWith("/")){try{java.io.InputStream in=Texture2D.class.getResourceAsStream(path);if(in==null)throw new IllegalStateException("Resource tekstur tidak ditemukan: "+path);extracted=java.nio.file.Files.createTempFile("visual-realism-texture-",".png");java.nio.file.Files.copy(in,extracted,java.nio.file.StandardCopyOption.REPLACE_EXISTING);in.close();loadPath=extracted.toAbsolutePath().toString();}catch(java.io.IOException ex){throw new java.io.UncheckedIOException(ex);}}
            ByteBuffer image=STBImage.stbi_load(loadPath,w,h,c,4);
            if(extracted!=null)try{java.nio.file.Files.deleteIfExists(extracted);}catch(java.io.IOException ignored){}if(image==null)throw new IllegalStateException("Tekstur gagal dimuat: "+STBImage.stbi_failure_reason());glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,w.get(0),h.get(0),0,GL_RGBA,GL_UNSIGNED_BYTE,image);glGenerateMipmap(GL_TEXTURE_2D);STBImage.stbi_image_free(image);}setFiltering(true);}public void setFiltering(boolean smooth){glBindTexture(GL_TEXTURE_2D,id);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,smooth?GL_LINEAR_MIPMAP_LINEAR:GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,smooth?GL_LINEAR:GL_NEAREST);}public void bind(int unit){glActiveTexture(GL_TEXTURE0+unit);glBindTexture(GL_TEXTURE_2D,id);}@Override public void close(){glDeleteTextures(id);}}
